define(["jquery","core/notification","core/str"],function($,Notification,Str){const init=()=>{$(document).on("submit",'[data-action="delete-caption"]',function(event){if(this.dataset.confirmed==="1"){return}event.preventDefault();const form=this;Promise.all([Str.get_string("deletecaptionconfirm","videoprogress"),Str.get_string("confirmdelete","videoprogress"),Str.get_string("cancel","videoprogress")]).then(strings=>Notification.confirm("",strings[0],strings[1],strings[2],()=>{form.dataset.confirmed="1";form.submit()}))})};return{init:init}});